  \begin{array}{ll}
  -\Delta u = \lambda u + \frac{Q(x)\left(|x|^a|Du|^p +|Du|^p\right)}{p}, 
  \displaystyle\frac{\partial u}{\partial x_1} = 0 \quad \mbox{on $\partial H_1$},
  \end{array}
  \right.
  \end{equation*}
